mapper.select:
SELECT *
FROM ads_event_overview
WHERE event_id = #{eventId}

SELECT *
FROM ads_content_hot_rank
WHERE event_id = #{eventId}
  AND platform <> 'WEIBO'
ORDER BY platform_heat_index DESC, hot_score DESC, publish_time DESC
LIMIT #{limit}

SELECT *
FROM ads_topic_summary
WHERE event_id = #{eventId}
ORDER BY peak_burst_index DESC, content_count DESC
LIMIT #{limit}

SELECT *
FROM ads_topic_key_content
WHERE event_id = #{eventId}
  AND topic_id = #{topicId}
ORDER BY publish_time ASC

SELECT *
FROM ads_keyword_rank
WHERE event_id = #{eventId}
ORDER BY word_count DESC
LIMIT #{limit}

SELECT *
FROM ads_content_hot_rank
WHERE event_id = #{eventId}
ORDER BY rank_no ASC
LIMIT #{limit}

SELECT *
FROM ads_content_hot_rank
WHERE event_id = #{eventId}
ORDER BY publish_time DESC, id DESC
LIMIT #{limit}
